class Solution {
public:
    vector<int> getOrder(vector<vector<int>>& tasks) {
        int n = tasks.size();
        vector<array<long long,3>> arr(n);
        for (int i = 0; i < n; i++) {
            arr[i] = {tasks[i][0], tasks[i][1], i};
        }
        sort(arr.begin(), arr.end());
        priority_queue<pair<long long,long long>,
                       vector<pair<long long,long long>>,
                       greater<pair<long long,long long>>> pq;
        vector<int> ans;
        ans.reserve(n);
        long long t = 0;
        int i = 0;
        while ((int)ans.size() < n) {
            while (i < n && arr[i][0] <= t) {
                pq.push({arr[i][1], arr[i][2]});
                i++;
            }
            if (pq.empty()) {
                t = arr[i][0];
                continue;
            }
            pair<long long,long long> top = pq.top();
            pq.pop();
            ans.push_back((int)top.second);
            t += top.first;
        }
        return ans;
    }
};
